insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 1, 'CONGRATULATIONS! You have won $850,000', 'CONGRATULATIONS!!!

Your email address was selected in our International Sweepstakes Draw and you have won $850,000.00 USD.

To release your winnings, a one-time processing fee of $250 must be paid. Claim your prize here:
{link}

This offer is confidential. Please do not share it with anyone until your funds have been released.

Prize Notification Center
Claims Department', 'Paying a fee to collect a prize is the core of the prize scam.', array['You can''t win a contest you never entered.','Real prizes don''t cost money to collect. Paying to receive money is always the scam.','Asking you to keep it secret keeps you from talking to someone who''d spot it straight away.']::text[], 'Prize scams have been around for a long time because the hope of a windfall is powerful. They all come down to one request, which is to send a little money to receive a lot. Once someone pays, the fees tend to keep coming: taxes, customs, insurance.', 'draft', '[{"quote":"Your email address was selected","note":"You can''t win a contest you never entered."},{"quote":"a one-time processing fee of $250","note":"Real prizes don''t cost money to collect. Paying to receive money is always the scam."},{"quote":"Please do not share it with anyone","note":"Asking you to keep it secret keeps you from talking to someone who''d spot it straight away."}]'::jsonb, '{"from_name":"Prize Notification Center","from_local":"winners"}'::jsonb, 'generic', null, 'human', array['If I didn''t enter, I didn''t win, so I''ll delete it.','I won''t pay anything to collect a prize.','If I''m tempted, I''ll show it to someone in the family first.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The amount of money","Having to pay a fee to receive the prize","The capital letters"],"correct":1,"affirm":"Yes. Paying to receive a prize is the giveaway, whatever the amount and however official it looks.","gently":"The big number and the capitals are suspicious too, but the clearest sign is the fee. Paying to receive a prize is the giveaway every time."}'::jsonb, '/scam-alerts/scams-targeting-seniors-2026'
