insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 1, 'WARNING: Virus detected on your computer', 'SECURITY WARNING

Our system has detected 5 viruses on your computer. Your personal files, photos and banking information may be at risk.

Do NOT turn off your computer. Doing so may cause permanent data loss.

Click below to speak with a certified technician immediately:
{link}

Computer Security Center', 'Unsolicited virus warnings that push you to contact a technician are tech support scams.', array['No company can see viruses on your computer from the outside and email you about them.','Turning it off is safe. This line is there to keep you anxious and on the hook.','The ''technician'' asks for remote access to your computer and then for payment, or for your bank login.']::text[], 'Tech support scams start with a scare and end with someone connected to your computer. Once they''re in, they ''find'' problems, charge for fixing them, and sometimes move on to your bank account. Real security software doesn''t email you a phone number to call.', 'draft', '[{"quote":"Our system has detected 5 viruses on your computer","note":"No company can see viruses on your computer from the outside and email you about them."},{"quote":"Do NOT turn off your computer","note":"Turning it off is safe. This line is there to keep you anxious and on the hook."},{"quote":"speak with a certified technician immediately","note":"The ''technician'' asks for remote access to your computer and then for payment, or for your bank login."}]'::jsonb, '{"from_name":"Computer Security Alert","from_local":"security-alert"}'::jsonb, 'generic', null, 'human', array['I''ll close the email and won''t call or click anything in it.','If I''m worried about my computer, I''ll ask someone I know, or take it to a local shop I chose myself.','I won''t let anyone I didn''t contact first connect to my computer.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["An email claiming it can see viruses on your computer","The warning about turning off the computer","The word ''certified''"],"correct":0,"affirm":"That''s it. Nobody can see what''s on your computer from the outside and email you about it, so the whole message falls apart right there.","gently":"That line is meant to scare you, so it''s a good one to notice. The first sign, though, is the claim itself: nobody can see what''s on your computer from the outside and email you about it."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
