insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 1, 'Your account has been locked', 'Dear Valued Member,

We noticed unusual sign-in activity on your account and have temporarily locked it for your protection.

To unlock your account, please verify your identity, including your card number and PIN, within 12 hours:
{link}

If you do not verify, your account will be permanently closed.

Thank you,
Account Security Team', 'Your bank never asks for your PIN or card number by email.', array['Your bank knows your name and uses it.','No bank ever asks for your PIN, by email or any other way.','The threat is there to rush you. Banks don''t close accounts because you didn''t click a link.']::text[], 'Account-locked emails work because they make you feel your money is in danger and offer a quick fix. The fix is the trap. If something really were wrong, you''d find out by calling the number on your card or signing in the way you normally do.', 'draft', '[{"quote":"Dear Valued Member","note":"Your bank knows your name and uses it."},{"quote":"your card number and PIN","note":"No bank ever asks for your PIN, by email or any other way."},{"quote":"your account will be permanently closed","note":"The threat is there to rush you. Banks don''t close accounts because you didn''t click a link."}]'::jsonb, '{"from_name":"Account Security Team","from_local":"account-security"}'::jsonb, 'generic', null, 'human', array['I''ll call the number on the back of my card and ask if anything''s wrong.','I''ll sign in the way I always do, by typing the bank''s address myself, never from a link.','I''ll never give my PIN to anyone.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The email mentions unusual activity","It asks for your card number and PIN","It was sent by a security team"],"correct":1,"affirm":"Yes. A bank will never ask for your PIN, so that request alone tells you it''s a scam.","gently":"Real banks do sometimes mention unusual activity, which is why this one is convincing. The giveaway is the request for your PIN. A bank will never ask for it."}'::jsonb, null
