with scam as (insert into public.practice_scams(stable_code,name,category) values('family-new-email','"It''s me" from a new address','family_emergency') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 2, 'It''s me, I lost my phone', 'Hi, it''s me. I lost my phone and I''m using a friend''s email for now, so don''t use my old number.

I''m in a bit of trouble and I really need your help. I need to pay something today and my cards aren''t working. Can you send $600? I''ll pay you back as soon as I sort this out.

Please don''t tell Mom or Dad yet, I''ll explain everything later.

Here''s where you can send it:
{link}

Thank you so much, I love you.', '"It''s me" messages from a new address asking for urgent, secret money are family emergency scams.', array['Someone you know would use their name. ''It''s me'' lets you fill in who you think it is.','This stops you from calling them back to check, which is exactly what you should do.','Asking you to keep it secret keeps you from hearing that they''re perfectly fine.']::text[], 'This is the email version of the grandparent scam. It works because it lands on love and worry at the same time. The details that make it effective, a new address, a secret, a deadline, are the same ones that give it away. Calling the number you already have settles it in a minute.', 'draft', '[{"quote":"Hi, it''s me","note":"Someone you know would use their name. ''It''s me'' lets you fill in who you think it is."},{"quote":"don''t use my old number","note":"This stops you from calling them back to check, which is exactly what you should do."},{"quote":"Please don''t tell Mom or Dad yet","note":"Asking you to keep it secret keeps you from hearing that they''re perfectly fine."}]'::jsonb, '{"from_name":"Me (new email)","from_local":"its-me"}'::jsonb, 'generic', null, 'human', array['I''ll call them on the number I already have, whatever the message says.','If I can''t reach them, I''ll call someone else in the family before I send anything.','I won''t send money to a link or a new account because of a message.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The message says ''I love you''","It asks you not to use their old number and to keep it secret","It asks for $600 instead of a larger amount"],"correct":1,"affirm":"Exactly. Being steered away from calling them and from telling the family is how these scams keep you from finding out the truth.","gently":"The amount can feel reassuring, which is part of the trick. The clearest sign is being steered away from calling them and from telling the family."}'::jsonb, '/scam-alerts/ai-voice-cloning-grandparent-scam'
