with scam as (insert into public.practice_scams(stable_code,name,category) values('medicare-plan-change','Medicare plan ending','medicare') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Important: changes to your Medicare coverage for 2027', 'Dear Beneficiary,

During this year''s Open Enrollment period, your current plan has been flagged for changes that may affect your coverage starting January 1.

To avoid a gap in coverage, please review and confirm your plan within 48 hours. You will need your Medicare number to continue.

Review your coverage:
{link}

If you have already reviewed your plan, you may ignore this message.

Medicare Benefits Office
Beneficiary Services', 'Medicare doesn''t email asking for your Medicare number, and Open Enrollment deadlines aren''t 48 hours.', array['Open Enrollment runs for weeks. Nobody official gives you 48 hours to act.','Your Medicare number is valuable to scammers, who use it to bill for things you never got. Keep it for your doctors and pharmacy.','Medicare doesn''t email you to ask for your number. If something needed checking, you''d get a letter.']::text[], 'This one is harder because it arrives during real Open Enrollment, when you''re expecting mail about your plan. The polite last line (''you may ignore this message'') makes it feel routine. What gives it away is the short deadline and the request for your Medicare number.', 'draft', '[{"quote":"within 48 hours","note":"Open Enrollment runs for weeks. Nobody official gives you 48 hours to act."},{"quote":"You will need your Medicare number to continue","note":"Your Medicare number is valuable to scammers, who use it to bill for things you never got. Keep it for your doctors and pharmacy."},{"quote":"Medicare Benefits Office","note":"Medicare doesn''t email you to ask for your number. If something needed checking, you''d get a letter."}]'::jsonb, '{"from_name":"Medicare Benefits Office","from_local":"benefits"}'::jsonb, 'generic', '2026-12-08'::timestamptz, 'human', array['I''ll call the number on my Medicare card, or 1-800-MEDICARE, if I want to check my plan.','I won''t type my Medicare number into a link from an email.','I''ll review plans with someone I trust, like a local SHIP counselor.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions Open Enrollment","It asks for your Medicare number with a 48-hour deadline","It says you may ignore it"],"correct":1,"affirm":"That''s right. A short deadline plus a request for your Medicare number is the combination to watch for.","gently":"It does feel more trustworthy because it mentions the real Open Enrollment. The giveaway is the 48-hour deadline and the request for your Medicare number."}'::jsonb, '/scam-alerts/medicare-open-enrollment-scams'
