insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'You have a pending tax refund of $1,284.00', 'Hello,

After a review of your recent tax filing, we have determined that you are eligible for an additional refund of $1,284.00.

To receive your refund by direct deposit, please confirm your bank account details and Social Security number using the secure form below:
{link}

Refunds not claimed within 5 business days will be returned to the Treasury.

Tax Refund Department
Taxpayer Services', 'The tax agency doesn''t email about refunds or ask for your Social Security number by email.', array['The tax agency contacts people by post, not by email, and certainly not to hand out surprise money.','These two together are what someone needs to take over your accounts or file a return in your name.','A refund you''re owed doesn''t vanish because you didn''t click quickly.']::text[], 'A refund email is pleasant to get, which is why it works better than a threat for some people. Good news can lower your guard. The request for your bank details and Social Security number is what to notice.', 'draft', '[{"quote":"eligible for an additional refund of $1,284.00","note":"The tax agency contacts people by post, not by email, and certainly not to hand out surprise money."},{"quote":"your bank account details and Social Security number","note":"These two together are what someone needs to take over your accounts or file a return in your name."},{"quote":"within 5 business days","note":"A refund you''re owed doesn''t vanish because you didn''t click quickly."}]'::jsonb, '{"from_name":"Tax Refund Department","from_local":"refunds"}'::jsonb, 'generic', null, 'human', array['If I think I''m owed a refund, I''ll check on the tax agency''s website by typing the address myself.','I''ll never send my Social Security number in reply to an email.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The refund amount","Being asked for your bank details and Social Security number by email","The word ''Treasury''"],"correct":1,"affirm":"Yes. Nobody official asks for your Social Security number and bank details through an email link.","gently":"The exact amount is there to seem believable. The clearest sign is the request for your Social Security number and bank details, which nobody official asks for by email."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('subscription-renewal-refund','Surprise renewal charge','tech_support') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Receipt: your annual protection plan has renewed ($399.99)', 'Thank you for your purchase.

Your annual Device Protection Plan has been renewed automatically.

Amount charged: $399.99
Payment method: card on file
Renewal period: 12 months

If you did not authorize this renewal, you have 24 hours to request a refund. To cancel and receive your refund, open your billing page:
{link}

Billing Support Team', 'Fake renewal receipts push you to ''cancel'' through a scammer.', array['If you don''t recognize the plan, that''s because there isn''t one. The surprise is meant to send you straight to the link.','The rush makes you act before checking your actual bank or card statement.','The ''refund'' is the trap. These scams end with someone on your computer ''fixing'' an overpayment from your bank account.']::text[], 'Fake receipts are clever because they make you want to act to protect yourself. The urge to get your money back is what sends people to the link or phone number. Your real statement will tell you whether anything was charged.', 'draft', '[{"quote":"Your annual Device Protection Plan","note":"If you don''t recognize the plan, that''s because there isn''t one. The surprise is meant to send you straight to the link."},{"quote":"you have 24 hours to request a refund","note":"The rush makes you act before checking your actual bank or card statement."},{"quote":"To cancel and receive your refund","note":"The ''refund'' is the trap. These scams end with someone on your computer ''fixing'' an overpayment from your bank account."}]'::jsonb, '{"from_name":"Billing Support","from_local":"billing"}'::jsonb, 'generic', null, 'human', array['I''ll check my bank or card statement directly to see if there''s really a charge.','If I see a charge I don''t recognize, I''ll call the number on the back of my card.','I won''t call or click anything in a receipt I don''t recognize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A receipt for a plan you never bought, pushing you to cancel within 24 hours","The word ''receipt''","The amount ending in .99"],"correct":0,"affirm":"Right. A charge you don''t recognize with a short refund window is the setup, and checking your own statement takes the sting out of it.","gently":"Prices ending in .99 are common in real receipts too. The clearest sign is a charge for something you never bought, paired with a rush to ''cancel''."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('romance-wrong-address','Friendly stranger with photos','romance') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'I think I have the wrong email, sorry!', 'Hello,

I''m so sorry, I think I have written to the wrong address. I was trying to reach an old friend from my time in the service. I hope I am not bothering you.

You seem like a kind person, and to be honest it has been a lonely year since I lost my wife. I am working overseas on an engineering contract right now.

If you would like to talk, I would enjoy that very much. Here are some photos from where I am working:
{link}

Warm wishes,
Daniel', '"Wrong address" openers from lonely, overseas strangers are how romance scams begin.', array['The ''wrong address'' opener is a way to start a conversation with a stranger without looking like a sales pitch.','Sharing a loss straight away builds sympathy fast. It''s a common opening in romance scams.','Working abroad explains why they can never meet or video call, and later why they need money sent.']::text[], 'Romance scams start slowly and kindly, and money doesn''t come up for weeks or months. That''s why the opening is the best place to spot them. A stranger who writes ''by mistake'', shares a loss and lives somewhere far away fits a pattern scammers follow closely.', 'draft', '[{"quote":"I think I have written to the wrong address","note":"The ''wrong address'' opener is a way to start a conversation with a stranger without looking like a sales pitch."},{"quote":"it has been a lonely year since I lost my wife","note":"Sharing a loss straight away builds sympathy fast. It''s a common opening in romance scams."},{"quote":"working overseas on an engineering contract","note":"Working abroad explains why they can never meet or video call, and later why they need money sent."}]'::jsonb, '{"from_name":"Daniel","from_local":"daniel.w"}'::jsonb, 'generic', null, 'human', array['I won''t reply to messages from strangers who wrote to me ''by mistake''.','I won''t click photos or links from someone I don''t know.','If I do start talking to someone online, I''ll never send money to a person I haven''t met.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["He says he''s sorry","A stranger writing ''by mistake'', sharing a loss and working overseas","He signs off with ''Warm wishes''"],"correct":1,"affirm":"Yes. That opening pattern is how these scams usually start, long before money comes up.","gently":"Politeness is part of the charm, so it''s easy to warm to. The pattern to notice is the ''wrong address'' start, the quick sharing of a loss, and the job overseas."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('voter-registration-problem','Voter registration problem','election') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Action required: issue with your voter registration', 'Dear Voter,

During a routine review of voter rolls, we found a problem with your registration that may prevent you from voting in the upcoming election.

To keep your registration active, please confirm your identity, including your date of birth and the last four digits of your Social Security number, before the deadline:
{link}

Registrations that are not confirmed may be removed from the rolls.

Election Records Office
Voter Services Division', 'Election offices don''t email asking for your Social Security number to keep you registered.', array['Election offices send problems by post, and you can always check your own registration on your state''s official website.','Nobody needs your Social Security number by email to keep you registered.','The threat of losing your vote is meant to make you act fast.']::text[], 'Election-season scams pick up in the weeks before a vote, when people care most about being able to take part. You can check your own registration on your state''s website in a couple of minutes, which is much safer than any link.', 'draft', '[{"quote":"we found a problem with your registration","note":"Election offices send problems by post, and you can always check your own registration on your state''s official website."},{"quote":"the last four digits of your Social Security number","note":"Nobody needs your Social Security number by email to keep you registered."},{"quote":"may be removed from the rolls","note":"The threat of losing your vote is meant to make you act fast."}]'::jsonb, '{"from_name":"Election Records Office","from_local":"voter-records"}'::jsonb, 'generic', '2026-11-04'::timestamptz, 'human', array['I''ll check my registration on my state''s official election website by typing it in myself.','I''ll call my county election office if I''m unsure.','I won''t give personal details through an email link.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The email mentions the upcoming election","It asks for part of your Social Security number by email","It calls you ''Dear Voter''"],"correct":1,"affirm":"Right. No election office asks for your Social Security number through an email link.","gently":"The timing makes it feel real, which is why it works. The clearest sign is the request for your Social Security number, which no election office makes by email."}'::jsonb, '/scam-alerts/weekly-2026-10-19'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('benefits-suspended','Benefits suspended','government') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Your benefits have been suspended', 'Notice of Suspension

Your monthly benefits have been suspended due to suspicious activity linked to your Social Security number.

To reinstate your benefits and avoid a permanent hold, you must verify your identity today. A case officer has been assigned to your file.

Verify and speak with your case officer:
{link}

Case reference: BA-2207-44

Benefits Administration
Office of Inspector Services', 'Benefits aren''t suspended by email, and Social Security numbers can''t be suspended.', array['Your number can''t be ''suspended'', and benefits aren''t stopped by email.','The ''case officer'' is the scammer. The official-sounding role is there to make you trust them.','A reference number makes it look official. Anyone can make one up.']::text[], 'Government impersonation scams take a real worry, losing income you rely on, and attach official-sounding details to it. The reference number and the case officer are props. A call to the agency on a number you looked up yourself clears it up.', 'draft', '[{"quote":"suspended due to suspicious activity linked to your Social Security number","note":"Your number can''t be ''suspended'', and benefits aren''t stopped by email."},{"quote":"A case officer has been assigned to your file","note":"The ''case officer'' is the scammer. The official-sounding role is there to make you trust them."},{"quote":"Case reference: BA-2207-44","note":"A reference number makes it look official. Anyone can make one up."}]'::jsonb, '{"from_name":"Benefits Administration","from_local":"benefits-admin"}'::jsonb, 'generic', null, 'human', array['I''ll call the agency on a number I look up myself.','I''ll check my benefits by signing in to the official website the usual way.','I won''t call a ''case officer'' named in an email.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The case reference number","A claim that your benefits were suspended by email over your Social Security number","The word ''Inspector''"],"correct":1,"affirm":"Yes. Benefits aren''t suspended by email, so the claim itself gives it away.","gently":"The reference number is there to make it feel official. The real giveaway is the claim itself: benefits aren''t suspended by email."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('customs-duty-package','Customs fee on a package','delivery') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Customs clearance required for your shipment', 'Hello,

A package addressed to you is being held at customs pending payment of import duties.

Shipment ID: 7740-2219-US
Duty owed: $12.60

Please pay the duty within 3 days to release your package. After that, it will be returned to the sender and a storage fee will apply.

Pay customs duty:
{link}

International Shipping Customs
Clearance Department', 'Surprise customs fees by email are a variation on the delivery fee scam.', array['If you ordered from abroad, the shop or carrier tells you about duties at checkout or on delivery, not in a surprise email.','A small, exact amount feels routine. The real aim is your card number.','Adding a penalty is another way to hurry you.']::text[], 'This is a close cousin of the redelivery fee scam, dressed up with a shipment ID to look official. Most people don''t know how customs fees work, which is what makes it believable.', 'draft', '[{"quote":"being held at customs pending payment of import duties","note":"If you ordered from abroad, the shop or carrier tells you about duties at checkout or on delivery, not in a surprise email."},{"quote":"Duty owed: $12.60","note":"A small, exact amount feels routine. The real aim is your card number."},{"quote":"a storage fee will apply","note":"Adding a penalty is another way to hurry you."}]'::jsonb, '{"from_name":"International Shipping Customs","from_local":"customs"}'::jsonb, 'generic', null, 'human', array['I''ll check the order on the shop''s own website if I''m expecting something.','I won''t pay a customs fee from an email link.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The shipment ID number","A surprise email asking you to pay a customs fee through a link","The package going back to the sender"],"correct":1,"affirm":"Right. A surprise fee to pay through a link is the sign, however official the shipment number looks.","gently":"The shipment ID is there to look official. The clearest sign is being asked to pay a surprise fee through a link."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('shared-document-sign-in','Shared document sign-in','account_takeover') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'A document has been shared with you: Family Photos 2026', 'A document has been shared with you.

Family Photos 2026.pdf
(18 pages)

To view this document, sign in with your email address and password:
{link}

This link will expire in 48 hours.

You received this email because someone shared a file with you.', 'Fake shared-document notices collect email passwords.', array['A sign-in page reached from an email link is how passwords are collected. Your email password is the key to all your other accounts.','A real share notice tells you who shared it. ''Someone'' keeps it vague so you''ll assume it''s family.','A tempting, personal-sounding file name is bait.']::text[], 'Whoever has your email password can reset nearly every other password you have, which is why this simple-looking scam is so valuable to criminals. Asking the person who supposedly sent it is the fastest check.', 'draft', '[{"quote":"sign in with your email address and password","note":"A sign-in page reached from an email link is how passwords are collected. Your email password is the key to all your other accounts."},{"quote":"someone shared a file with you","note":"A real share notice tells you who shared it. ''Someone'' keeps it vague so you''ll assume it''s family."},{"quote":"Family Photos 2026.pdf","note":"A tempting, personal-sounding file name is bait."}]'::jsonb, '{"from_name":"Shared Files","from_local":"share-notify"}'::jsonb, 'generic', null, 'human', array['If I''m expecting photos, I''ll ask the person directly whether they sent them.','I won''t type my email password into a page I reached from an email.','If I already did, I''ll change my password and tell someone who can help.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The file is a PDF","It doesn''t say who shared it and asks for your email password","It mentions the year"],"correct":1,"affirm":"Yes. A vague ''someone'' plus a request for your password is the pattern to watch for.","gently":"The details are there to make it feel personal. The sign to notice is that it doesn''t say who shared it, then asks for your password."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('bank-safe-account','Bank fraud team and a "safe account"','bank') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 4, 'Re: Case 55120 - protecting your savings', 'Hello,

Following up on our fraud alert from this morning. We have confirmed that an employee at your local branch may be involved in unauthorized activity on several customer accounts, including yours.

For your protection, we have opened a temporary secure account in your name. Please move your savings into it today so they can''t be accessed. The details are here:
{link}

For your safety, please do not discuss this with branch staff, as the investigation is ongoing.

Fraud Prevention Department', 'Banks never ask you to move money to a ''safe account'' or to keep it from branch staff.', array['Pretending to continue an earlier conversation makes you think you''ve already checked. You haven''t.','A real bank never asks you to move money to keep it safe. Your money is protected where it is.','The branch staff are exactly the people who''d tell you it''s a scam. That''s why they don''t want you talking to them.']::text[], 'The ''safe account'' scam is one of the most expensive there is, because people move their life savings believing they''re protecting them. It''s harder to spot because it borrows the language of fraud protection. Any request to move money to keep it safe is the scam, however it''s explained.', 'draft', '[{"quote":"Following up on our fraud alert from this morning","note":"Pretending to continue an earlier conversation makes you think you''ve already checked. You haven''t."},{"quote":"move your savings into it today","note":"A real bank never asks you to move money to keep it safe. Your money is protected where it is."},{"quote":"please do not discuss this with branch staff","note":"The branch staff are exactly the people who''d tell you it''s a scam. That''s why they don''t want you talking to them."}]'::jsonb, '{"from_name":"Fraud Prevention Department","from_local":"fraud-prevention"}'::jsonb, 'generic', null, 'human', array['I''ll hang up, or close the email, and call the number on the back of my card.','I''ll never move money to a ''safe account'' for anyone.','I''ll tell someone in the family before I move any money.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to move your savings and not tell branch staff","The case number in the subject","Being told about a fraud alert"],"correct":0,"affirm":"Exactly. A request to move money to keep it safe, plus keeping it from the branch, is the scam every time.","gently":"Real banks do send fraud alerts, which is why this one is convincing. The giveaway is being asked to move your savings and keep it from branch staff."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('order-shipped-unknown-address','Order shipped to a strange address','shopping') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 4, 'Your order #114-3920-5581 has shipped', 'Hello,

Good news, your order has shipped.

Item: 65" 4K Smart TV
Order total: $1,149.00
Shipping to: 2290 Lakeview Dr, Apt 4B
Estimated delivery: Friday

Don''t recognize this order or this address? Review your order and report it here:
{link}

Thank you for shopping with us.', 'Fake order confirmations use alarm about a stranger''s purchase to send you to a fake support page.', array['A strange address makes you worry someone is using your account, so you click to fix it.','This is the hook. The ''report'' link leads to a fake sign-in page or a fake support line.','A large purchase you didn''t make is meant to alarm you into acting fast.']::text[], 'This one looks exactly like the order emails people get every week, which is why it''s rated hard. There''s nothing obviously wrong with it. The way to check is the same as always: go to the shop yourself, not through the email.', 'draft', '[{"quote":"Shipping to: 2290 Lakeview Dr, Apt 4B","note":"A strange address makes you worry someone is using your account, so you click to fix it."},{"quote":"Don''t recognize this order or this address?","note":"This is the hook. The ''report'' link leads to a fake sign-in page or a fake support line."},{"quote":"Order total: $1,149.00","note":"A large purchase you didn''t make is meant to alarm you into acting fast."}]'::jsonb, '{"from_name":"Order Updates","from_local":"orders"}'::jsonb, 'generic', null, 'human', array['I''ll open the shop''s app or type its website myself and look at my orders there.','I''ll check my card statement for the charge.','I won''t use links or phone numbers in an order email I don''t recognize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The order number","An order you didn''t place, with a link to ''report'' it","The delivery day"],"correct":1,"affirm":"Yes. An order you didn''t place with a convenient ''report it here'' link is the setup. Checking your account yourself takes care of it.","gently":"The order number looks real, which is what makes this convincing. The sign is an order you didn''t place with a link to report it, which is where the trap is."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('patient-portal-message','New message from your care team','health') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 5, 'You have a new message from your care team', 'You have a new secure message.

A member of your care team has sent you a message about your recent visit, which may include test results.

To read it, sign in to the patient portal:
{link}

For your privacy, the message isn''t included in this email.

Please do not reply to this email. This mailbox is not monitored.', 'Look-alike portal notices collect sign-in details; always open the portal yourself.', array['Test results are something everyone wants to read straight away, and that urge is what this relies on. The email never names your doctor or clinic.','The link leads to a look-alike sign-in page. Open the portal the way you usually do, from a bookmark or the clinic''s website.','Real portals say this too, which is why this one is so hard to spot. The difference is how you get there.']::text[], 'This is the hardest kind, because it''s nearly identical to a real notice. The only things missing are your doctor''s name and the clinic''s name. You don''t have to spot those to stay safe. If you always open the portal yourself, the link never matters.', 'draft', '[{"quote":"about your recent visit, which may include test results","note":"Test results are something everyone wants to read straight away, and that urge is what this relies on. The email never names your doctor or clinic."},{"quote":"sign in to the patient portal","note":"The link leads to a look-alike sign-in page. Open the portal the way you usually do, from a bookmark or the clinic''s website."},{"quote":"For your privacy, the message isn''t included in this email","note":"Real portals say this too, which is why this one is so hard to spot. The difference is how you get there."}]'::jsonb, '{"from_name":"Patient Portal","from_local":"portal-notify"}'::jsonb, 'generic', null, 'human', array['I''ll open the patient portal from my own bookmark or the clinic''s website, never from the email.','If I''m not sure, I''ll call my doctor''s office.','I''ll notice when an email doesn''t name my doctor or clinic.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It doesn''t name your doctor or clinic","It says the mailbox isn''t monitored","It mentions privacy"],"correct":0,"affirm":"Well spotted. Without your doctor''s or clinic''s name, it could be from anyone, and opening the portal yourself sidesteps the whole thing.","gently":"Real portals say those things too, so this one is genuinely hard. The small sign is that it never names your doctor or clinic. Opening the portal yourself sidesteps the question."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('phantom-hacker-federal','Hacker warning and a federal agent','bank') on conflict(stable_code) do update set name=excluded.name returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 5, 'Security incident on your accounts: reference SP-40418', 'Hello,

We''re writing because our monitoring detected that your computer was accessed by an overseas group, and they may now be able to see your bank and retirement accounts.

This incident has been referred to a federal agency. An agent will contact you by phone today to help secure your funds. Please follow their instructions carefully and keep this matter confidential, including from family members, as it is part of an active investigation.

You can confirm your incident details here:
{link}

